describe('matchOp', () => {
  it('compares equality on the STRING form, so 200 and "200" agree', () => {
    expect(matchOp(200, 'eq', '200')).toBe(true);
    expect(matchOp('200', 'eq', 200)).toBe(true);
    expect(matchOp(200, 'neq', '201')).toBe(true);
  });
  it('handles presence — null and undefined are the only absences', () => {
    expect(matchOp(undefined, 'exists')).toBe(false);
    expect(matchOp(null, 'exists')).toBe(false);
    expect(matchOp('', 'exists')).toBe(true); // an empty string IS a value
    expect(matchOp('x', 'exists')).toBe(true);
    expect(matchOp(undefined, 'notExists')).toBe(true);
    expect(matchOp('x', 'notExists')).toBe(false);
  });
  it('matches a member of an array with contains', () => {
    expect(matchOp(['a', 'b'], 'contains', 'b')).toBe(true);
    expect(matchOp(['a'], 'contains', 'z')).toBe(false);
  });
  it('compares gte and lte inclusively', () => {
    expect(matchOp(5, 'gte', 5)).toBe(true);
    expect(matchOp(5, 'lte', 5)).toBe(true);
    expect(matchOp('x', 'gt', 1)).toBe(false); // non-numeric never orders
  });
  it('handles ordering and substrings', () => {
    expect(matchOp(5, 'gt', 3)).toBe(true);
    expect(matchOp(3, 'gt', 5)).toBe(false);
    expect(matchOp(3, 'lt', 5)).toBe(true);
    expect(matchOp('hello world', 'contains', 'lo w')).toBe(true);
    expect(matchOp('hello', 'contains', 'zz')).toBe(false);
  });
  it('is false for an operator it does not know', () => {
    expect(matchOp('x', 'nonsense' as never, 'x')).toBe(false);
  });
});

describe('getPath', () => {
  it('walks dots and array indexes', () => {
    const o = { a: { b: [{ c: 7 }] } };
    expect(getPath(o, 'a.b[0].c')).toBe(7);
    expect(getPath(o, 'a.b.0.c')).toBe(7);
  });
  it('answers undefined instead of throwing on a missing branch', () => {
    expect(getPath({ a: 1 }, 'a.b.c')).toBeUndefined();
    expect(getPath(null, 'a')).toBeUndefined();
    expect(getPath({ a: 1 }, '')).toBeDefined();
  });
});

describe('coercions', () => {
  it('toStr never prints an object marker', () => {
    expect(toStr('a')).toBe('a');
    expect(toStr(3)).toBe('3');
    expect(toStr(null)).toBe('');
    expect(toStr(undefined)).toBe('');
    expect(toStr({ a: 1 })).not.toContain('[object');
  });
  it('asList always yields an array', () => {
    expect(asList([1, 2])).toEqual([1, 2]);
    expect(asList(null)).toEqual([]);
    expect(asList(undefined)).toEqual([]);
    // a single object becomes a one-item list, never an unwrapped envelope
    expect(asList({ a: 1 })).toEqual([{ a: 1 }]);
  });
  it('boolish reads the words a payload actually uses', () => {
    expect(boolish(true)).toBe(true);
    expect(boolish('true')).toBe(true);
    expect(boolish('yes')).toBe(true);
    expect(boolish('1')).toBe(true);
    expect(boolish('false')).toBe(false);
    expect(boolish('')).toBe(false);
    expect(boolish(0)).toBe(false);
  });
});

describe('settled / resStatus / parseErrorBody', () => {
  it('reports a query that succeeded', () => {
    const s = settled({ isSuccess: true, data: { status: 201, body: { ok: 1 } } });
    expect(s.status).toBeGreaterThanOrEqual(200);
  });
  it('reports a query that failed', () => {
    const s = settled({ isSuccess: false, error: new AppError('server', 'boom', { status: 500 }) });
    expect(s.status).toBe(500);
    expect(settled({ isSuccess: false, error: null }).status).toBe(0);
  });
  it('falls back when a body carries no status', () => {
    // apiFetch stamps the real status as a non-enumerable __status; a plain
    // `status` field in a body is the API's own data, not the HTTP status
    expect(resStatus({}, 204)).toBe(204);
    expect(resStatus({ status: 404 })).toBe(200);
    expect(resStatus({ __status: 201 })).toBe(201);
    expect(resStatus(null)).toBe(200);
  });
  it('unwraps an error body', () => {
    expect(parseErrorBody(new AppError('server', 'x', { status: 500, cause: { body: '{"detail":"y"}' } }))).toBeDefined();
    expect(parseErrorBody(null)).toBeUndefined();
  });
});

describe('response rules', () => {
  // typed as ResponseRule[]: the app's tsc is a gate, and jest strips types, so
  // an untyped literal here passes the suite and fails the build
  const rules: ResponseRule[] = [
    { source: 'body', op: 'eq', path: 'code', value: 'OK', navigateTo: 'Home' },
    { source: 'body', op: 'exists', path: 'error', navigateTo: 'Failure' },
  ];
  it('takes the FIRST rule that matches', () => {
    expect(firstMatchingRule(rules, { code: 'OK' }, 200)?.navigateTo).toBe('Home');
    expect(firstMatchingRule(rules, { error: 'nope' }, 400)?.navigateTo).toBe('Failure');
  });
  it('answers null when nothing matches', () => {
    expect(firstMatchingRule(rules, { code: 'NO' }, 200)).toBeNull();
  });
  it('firstRuleTarget names the destination without evaluating a body', () => {
    expect(firstRuleTarget(rules, { code: 'OK' }, 200)).toBe('Home');
    expect(firstRuleTarget([], {}, 200)).toBeNull();
  });
});

describe('errors', () => {
  it('maps a status onto a kind', () => {
    expect(toAppError(new AppError('auth', 'no', { status: 401 })).kind).toBe('auth');
    expect(toAppError({ status: 404 }).kind).toBe('notFound');
    expect(toAppError({ status: 500 }).kind).toBe('server');
    expect(toAppError(new TypeError('Network request failed')).kind).toBe('network');
    expect(toAppError('weird').kind).toBe('unknown');
  });
  it('finds a human message in the shapes servers actually send', () => {
    expect(pickMessage({ message: 'a' })).toBe('a');
    expect(pickMessage({ error: { message: 'b' } })).toBe('b');
    expect(pickMessage({ errors: [{ message: 'c' }] })).toBe('c');
    expect(pickMessage(undefined)).toBeUndefined();
  });
  it('always produces something showable', () => {
    expect(errorMessage(new AppError('server', 'boom', { status: 500 }))).toBeTruthy();
    expect(errorMessage(null)).toBeTruthy();
    expect(responseMessage({ message: 'from body' })).toBe('from body');
  });
  it('fireAndForget swallows a rejection instead of crashing the app', async () => {
    const warn = jest.spyOn(console, 'warn').mockImplementation(() => undefined);
    fireAndForget(Promise.reject(new Error('ignored')), 'label');
    fireAndForget(undefined);
    await new Promise((r) => setImmediate(r));
    expect(warn).toHaveBeenCalled();
    warn.mockRestore();
  });
});

