describe('env', () => {
  it('returns the fallback for an unset key', () => {
    expect(env('DEFINITELY_NOT_SET', 'fb')).toBe('fb');
  });
  it('throws for a REQUIRED key that is unset — a silent empty string is worse', () => {
    expect(() => requireEnv('DEFINITELY_NOT_SET')).toThrow();
  });
  it('returns the value for a key that IS set', () => {
    // whichever vars this build baked in; ENV is the map env() reads
    const [key, value] = Object.entries(ENV).find(([, v]) => typeof v === 'string' && v !== '') ?? [];
    if (key === undefined) return; // a build with no env vars at all
    expect(requireEnv(key)).toBe(value);
    expect(env(key, 'unused-fallback')).toBe(value);
  });
});
